//! 🔢️ Public scalar original-source, denied-axis, finite-work and physical close laws.
use semio_framework_value_retained_clone::*;
#[path="../../../🧪️tests/⏱️effect/🦀️.rs"]
mod effect;
use semio_framework_value_clone_source::RetainedCloneSource;
use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
fn denied(grant:RetainedCloneGrant,copy_demand:usize)->Vec<RetainedCloneGrant>{
    [Some(RetainedCloneGrant {maximum_items:0,..grant}),copy_demand.checked_sub(1).map(|maximum_copy_bytes|RetainedCloneGrant {maximum_copy_bytes,..grant}),grant.maximum_capacity_bytes.checked_sub(1).map(|maximum_capacity_bytes|RetainedCloneGrant {maximum_capacity_bytes,..grant}),grant.maximum_release_bytes.checked_sub(1).map(|maximum_release_bytes|RetainedCloneGrant {maximum_release_bytes,..grant}),grant.maximum_depth.checked_sub(1).map(|maximum_depth|RetainedCloneGrant {maximum_depth,..grant}),(grant.maximum_release_bytes>8).then_some(RetainedCloneGrant {maximum_release_bytes:8,..grant})].into_iter().flatten().collect()
}

fn check_denied(turn:OriginalRetirementOutcome,heap:(usize,usize),grant:RetainedCloneGrant,admitted:RetainedCloneGrant){
    assert_eq!(turn.work,0);let result=turn.result;assert_eq!(heap,(0,0));match result{Ok(step)=>assert_eq!(step.progress(),Default::default()),Err(error)=>{assert!(grant.maximum_depth<admitted.maximum_depth);assert_eq!(error.primary().unwrap().kind,ValueRefusalKind::DepthLimit);assert_eq!(error.retained_progress(),Default::default());}}
}

#[test]
fn original_scalar_clone_requires_original_authority(){
    let law:serde_json::Value=serde_json::from_str(include_str!("../../../../🧮️scalar/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
    for encoded in law["values"].as_array().unwrap(){let value:u64=encoded.as_str().unwrap().parse().unwrap();for copy in law["copyGrants"].as_array().unwrap(){let copy=copy.as_u64().unwrap()as usize;for cancelled in [None,Some(0),Some(1)]{let mut cpu=law["closeWork"]["maximumCpu"].as_u64().unwrap();
        let(mut source,p,work)=effect::admit(value);cpu=cpu.checked_sub(u64::try_from(work).unwrap()).expect("same finite scalar CPU bank");let(mut born,mut freed)=(p.retained_capacity_bytes,p.released_bytes);let original=source.borrow().get()as *const u64;
        let(mut cursor,heap)=observe(u64::retained_clone_cursor);assert_eq!(heap,(0,0));let normal=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:law["payloadBytes"].as_u64().unwrap()as usize,maximum_depth:law["depth"].as_u64().unwrap()as usize,..Default::default()};
        if cancelled!=Some(0){for denied in [RetainedCloneGrant {maximum_items:0,..normal},RetainedCloneGrant {maximum_copy_bytes:0,..normal},RetainedCloneGrant {maximum_copy_bytes:normal.maximum_copy_bytes-1,..normal},RetainedCloneGrant {maximum_depth:0,..normal}]{let(turn,heap)=observe(||effect::advance(&mut cursor,source.borrow(),normal.maximum_copy_bytes,cpu,denied));assert_eq!(turn.work,u128::from(law["advanceWork"]["deniedCpu"].as_u64().unwrap()));let result=turn.result;assert_eq!(heap,(0,0));match result{Ok(step)=>assert_eq!(step.progress(),Default::default()),Err(error)=>{assert_eq!(denied.maximum_depth,0);assert_eq!(error.primary().unwrap().kind,ValueRefusalKind::DepthLimit);assert_eq!(error.retained_progress(),Default::default());}}assert_eq!(source.borrow().get()as *const u64,original);assert!(!cursor.output_ready());}
            {let funded=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:cursor.advance_demands(source.borrow(),normal.maximum_copy_bytes,cpu).unwrap().copy_bytes,maximum_depth:normal.maximum_depth,..Default::default()};let(result,heap)=observe(||effect::advance(&mut cursor,source.borrow(),normal.maximum_copy_bytes,cpu,funded));assert_eq!(result.work,u128::from(law["advanceWork"]["bindingCpu"].as_u64().unwrap()));cpu-=u64::try_from(result.work).unwrap();let bind=result.result.unwrap();assert_eq!(funded.maximum_copy_bytes,source.borrow().binding_copy_bytes());assert!(source.borrow().binding_copy_bytes()>=std::mem::size_of::<RetainedCloneBinding>());assert!(matches!(bind,RetainedCloneStep::Progress(_)));assert_eq!(heap,(0,0));assert_eq!(bind.progress(),RetainedCloneProgress {copied_items:1,copied_bytes:source.borrow().binding_copy_bytes(),..Default::default()});}
            let(result,heap)=observe(||effect::advance(&mut cursor,source.borrow(),normal.maximum_copy_bytes,cpu,normal));assert_eq!(result.work,u128::from(law["advanceWork"]["payloadCpu"].as_u64().unwrap()));cpu-=u64::try_from(result.work).unwrap();let step=result.result.unwrap();assert!(matches!(step,RetainedCloneStep::Complete(_)));assert_eq!(heap,(0,0));assert_eq!(step.progress(),RetainedCloneProgress {copied_items:1,copied_bytes:law["payloadBytes"].as_u64().unwrap()as usize,..Default::default()});if cancelled.is_none(){let handoff=RetainedCloneGrant{maximum_copy_bytes:cursor.take_demand().unwrap().copy_bytes,..normal};let(turn,heap)=observe(||effect::take(&mut cursor,handoff));cpu=cpu.checked_sub(u64::try_from(turn.work).unwrap()).expect("same finite scalar CPU bank");assert_eq!(turn.work,1);let output=turn.result.unwrap();assert_eq!(heap,(0,0));assert_eq!(output,Some((value,RetainedCloneProgress{copied_items:1,copied_bytes:handoff.maximum_copy_bytes,..Default::default()})));}
        }
        let started=RetainedCloneGrant{maximum_copy_bytes:cursor.begin_close_demand().unwrap().copy_bytes,..normal};let(turn,heap)=observe(||effect::begin_close_paid(&mut cursor,started));assert_eq!(heap,(0,0));cpu=cpu.checked_sub(u64::try_from(turn.work).unwrap()).expect("same finite close CPU bank");turn.result.unwrap();let mut turns=0;while !cursor.terminal_is_empty(){let d=cursor.close_demands(copy).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};assert_eq!(cursor.close_demands(grant.maximum_copy_bytes).unwrap(),d);for denied in denied(grant,d.copy_bytes){let(result,heap)=observe(||effect::close_step(&mut cursor,denied));check_denied(result,heap,denied,grant);}let(result,heap)=observe(||effect::close_step(&mut cursor,grant));cpu=cpu.checked_sub(u64::try_from(result.work).unwrap()).expect("same finite close CPU bank");let step=result.result.unwrap();assert!(step.progress().fits(grant));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));born+=heap.0;freed+=heap.1;turns+=1;assert!(turns<10000);}
        let cached=effect::close_step(&mut cursor,Default::default());assert_eq!(cached.work,u128::from(law["closeWork"]["cachedCpu"].as_u64().unwrap()));assert_eq!(cached.result.unwrap().progress(),Default::default());assert_eq!(observe(||drop(cursor)).1,(0,0));while !source.terminal_is_empty(){let d=source.next_close_demand(copy).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};assert_eq!(source.next_close_demand(grant.maximum_copy_bytes).unwrap(),d);for denied in denied(grant,d.copy_bytes){let(result,heap)=effect::driven(denied,|e|source.close_step(copy,e));check_denied(result,heap,denied,grant);}let(result,heap)=effect::driven(grant,|e|source.close_step(copy,e));cpu=cpu.checked_sub(u64::try_from(result.work).unwrap()).expect("same finite close CPU bank");let step=result.result.unwrap();assert!(step.progress().fits(grant));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));born+=heap.0;freed+=heap.1;turns+=1;assert!(turns<10000);}assert_eq!(observe(||drop(source)).1,(0,0));assert_eq!(born,freed);
    }}}
}

